import { expect, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test(
    "Documents from another tenant are invisible",
    { tag: "@DOC-07" },
    async ({ apiAs }) => {
      // Background: signed in as a Northwind member, with a vendor in status "draft"
      const northwind = await apiAs("member");
      const localVendor = await northwind.post("/api/vendors", {
        data: {
          name: uniqueName("Northwind Vendor"),
          category: "software",
          contact_email: `${uniqueName("nw").replace(/\s+/g, "-")}@example.test`,
        },
      });
      expect(localVendor.status()).toBe(201);
      expect((await localVendor.json()).status).toBe("draft");

      // Given a document exists in tenant "Globex Procurement"
      const globex = await apiAs("otherTenant");
      const globexVendor = await globex.post("/api/vendors", {
        data: {
          name: uniqueName("Globex Vendor"),
          category: "logistics",
          contact_email: `${uniqueName("gx").replace(/\s+/g, "-")}@example.test`,
        },
      });
      expect(globexVendor.status()).toBe(201);
      const globexVendorId = (await globexVendor.json()).id as string;

      const upload = await globex.post(`/api/vendors/${globexVendorId}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.txt",
            mimeType: "text/plain",
            buffer: Buffer.from("Globex W-9 test document"),
          },
        },
      });
      expect(upload.status()).toBe(201);
      const documentId = (await upload.json()).id as string;

      // When I request that document by id, as a Northwind member
      const response = await northwind.get(`/api/documents/${documentId}`);

      // Then the response status is 404 and the error code is "document_not_found"
      expect(response.status()).toBe(404);
      expect((await response.json()).error.code).toBe("document_not_found");
    },
  );
});
